(* [comment removed for export] *)
Definition supp_ok (b : expr) (off n : Z) : bool :=
  (0 <=? n) &&
  match b with
  | ELit z => (z =? 0) && (0 <=? off) && (off + n <=? 7077888)
  | EVar v => if Nat.eqb v 2 then (-128 <=? off) && (off + n <=? 0) && ((off + n <=? -96) || (-88 <=? off))
              else if Nat.eqb v 54 then (0 <=? off) && (off + n <=? 256) && ((off + n <=? 32) || (54 <=? off))
              else if Nat.eqb v 11 then (0 <=? off) && (off + n <=? 8)
              else if Nat.eqb v 32 then (0 <=? off) && (off + n <=? 24)
              else false
  | _ => match srl3_of b with
         | Some v => if Nat.eqb v 11 then (SBz <=? off) && (off + n <=? SBz + 1)
                     else if Nat.eqb v 54 then (SBz + 24 <=? off) && (off + n <=? SBz + 32) else false
         | None => false
         end
  end.
(* [comment removed for export] *)
Definition def_ok (b : expr) (off n : Z) : bool :=
  (0 <=? n) &&
  match b with
  | EVar v => if Nat.eqb v 2 then (-12544 <=? off) && (off + n <=? 0)
              else if (Nat.eqb v 54 || Nat.eqb v 49 || Nat.eqb v 11 || Nat.eqb v 32)%bool then (0 <=? off) else false
  | _ => match srl3_of b with
         | Some v => Nat.eqb v 54 && (SBz <=? off)
         | None => false
         end
  end.
