Definition wfacts (sp F sk s2 fl : Z) : Prop :=
  (7077888 <= F /\ (F + 256 <= 2147446784 \/ 17594333495296 <= F) /\ F + 256 <= sp - 288) /\
  (17592186044416 + 2147450880 + 288 <= sp /\ sp <= 2 ^ 47) /\
  (7077888 <= sk /\ sk + 8 <= 2 ^ 47 /\ (sk + 8 <= 2147446784 \/ 17594333495296 <= sk) /\ (F + 256 <= sk \/ sk + 8 <= F)
   /\ (F / 8 + 32 <= sk / 8 \/ sk / 8 + 1 <= F / 8) /\ (sp <= sk \/ sk + 8 <= sp - 12544)) /\
  (7077888 <= s2 /\ s2 + 24 <= 2 ^ 47 /\ (s2 + 24 <= 2147446784 \/ 17594333495296 <= s2) /\ (F + 256 <= s2 \/ s2 + 24 <= F) /\ s2 + 24 <= sp - 12544) /\
  7077888 <= fl.
Ltac bsplit H := repeat (lazymatch type of H with
  | (_ && _)%bool = true => let H1 := fresh "Hb" in apply andb_prop in H as [H H1]
  | (_ || _)%bool = true => apply orb_prop in H end).
Ltac zle_all := repeat (lazymatch goal with
  | H : (_ <=? _) = true |- _ => apply Z.leb_le in H
  | H : (_ =? _)%Z = true |- _ => apply Z.eqb_eq in H
  | H : ((_ <=? _) = true \/ _) |- _ => destruct H as [H|H]
  | H : (_ \/ (_ <=? _) = true) |- _ => destruct H as [H|H] end).
